import{expect,test}from'vitest'
const emit=row=>console.log('EXPECT_STATE_ROW '+JSON.stringify(row))
const shape=value=>({promise:value instanceof Promise,tag:Object.getOwnPropertyDescriptor(value,Symbol.toStringTag)?.value??null,then:typeof value.then,catch:typeof value.catch,finally:typeof value.finally})
test('unconsumed initial has no predicate work',()=>{let callbacks=0;expect.poll(()=>{callbacks++;return 1},{interval:1,timeout:1000});emit({kind:'initial-only',callbacks})})
test('actual matcher invocation owns lazy idempotent work',async()=>{let callbacks=0;const receivers=[];const events=[];const initial=expect.poll(function(){callbacks++;receivers.push(typeof this?.assert==='function');events.push('predicate');return 1},{interval:1,timeout:1000});const first=initial.toBe(1);emit({kind:'after-match',callbacks,shape:shape(first)});const waiting=first.then(()=>{events.push('fulfilled')});events.push('then-returned');queueMicrotask(()=>{events.push('queued-microtask')});emit({kind:'after-then',callbacks});await waiting;await first;emit({kind:'after-repeat-consume',callbacks,receivers:[...receivers],events:[...events]});const second=initial.toBe(1);emit({kind:'second-before-consume',callbacks,shape:shape(second)});await second;emit({kind:'second-settled',callbacks,receivers,events})})
test('unawaited matcher performs no predicate work',()=>{let callbacks=0;expect.poll(()=>{callbacks++;return 1},{interval:1,timeout:1000}).toBe(1);emit({kind:'unawaited-match',callbacks})})
